pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testFuzz_property(address sender) public {
        vm.assume(sender != address(0));
        address owner = c.owner();
        vm.startPrank(owner);
        c.pause();
        bool pausedAfterPause = c.paused();
        c.unPause();
        bool pausedAfterUnpause = c.paused();
        vm.stopPrank();
        assertTrue(pausedAfterPause && !pausedAfterUnpause);
    }
}
